#!/usr/bin/env bash
# Some portions generated by Codex. Prespecified four-arm Latin square, no adaptive extension.
set -euo pipefail
cd "$(dirname "$0")/../../.."
i=0
for arm in base depth both serializer depth serializer base both serializer both depth base both base serializer depth; do
 i=$((i+1))
 python3 experiments/threadlocal-audit/serializer-workbench/run.py "$arm" "matched-$(printf '%02d' "$i")-$arm" --warmups 60 --iterations 30
done
